#include "ptv/api/IDialogueHook.h"
#include "ptv/ecs/World.h"
#include <nlohmann/json.hpp>

#include <string>

namespace ptv {

// Forward decl in this TU
class MentorGuidanceDialogue;

} // namespace ptv

PTV_REGISTER_DIALOGUE_HOOK("generated.mentor_guidance_dialogue", ptv::MentorGuidanceDialogue)

#include <string>
#include <vector>
#include <unordered_map>
#include <algorithm>

namespace mentor_lines {

// Non-copyrighted, paraphrased guidance lines.
// Grouped by lightweight context keys consumed by the hook.

static const std::vector<std::string> kOnboard_CentralPlaza = {
    "Welcome, recruit. This plaza is your staging ground.",
    "Look toward the Central Battery. Breathe, steady your hands.",
    "Your ring shapes thought into action. Keep your focus light and direct."
};

static const std::vector<std::string> kOnboard_TrainingArena = {
    "Training ground ahead. Start simple: form a shield, then a clean strike.",
    "Mind your stance. Small movements read sharply in the ring.",
    "Build rhythm: guard, move, then commit."
};

static const std::vector<std::string> kTip_RepeatedFailure = {
    "Easy does it. Read the field before you rush.",
    "Lead with cover, then counter. Your will guides order into the chaos.",
    "If you’re pressed, shape a barrier and reset your angle."
};

static const std::vector<std::string> kPrompt_Recharge = {
    "Power dipping. Approach the recharge pedestal and align the ring.",
    "Hold still a moment. Let the current settle and restore your charge.",
    "When topped up, your constructs land clearer and hit truer."
};

static const std::vector<std::string> kOnboard_Generic = {
    "Eyes up. Center your breath, set your intent.",
    "Your will is the tool; the ring is the lens.",
    "Keep motions smooth—clean intent shapes clean light."
};

inline const std::vector<std::string>& select_block(const std::string& context,
                                                    const std::string& scene_id,
                                                    const std::string& reason)
{
    if (context == "scene_entry") {
        if (scene_id == "central_battery_plaza") return kOnboard_CentralPlaza;
        if (scene_id == "training_arena") return kOnboard_TrainingArena;
        return kOnboard_Generic;
    }
    if (context == "repeated_failure" || reason == "repeated_failure") {
        return kTip_RepeatedFailure;
    }
    if (context == "recharge_prompt" || reason == "low_energy_near_station") {
        return kPrompt_Recharge;
    }
    return kOnboard_Generic;
}

} // namespace mentor_lines

#include "ptv/api/IDialogueHook.h"
#include "ptv/ecs/World.h"
#include <nlohmann/json.hpp>

#include <string>
#include <vector>
#include <unordered_map>
#include <cstdint>
#include <optional>

namespace mentor_lines {
    const std::vector<std::string>& select_block(const std::string&, const std::string&, const std::string&);
}

namespace ptv {

// Minimal per-entity dialogue state kept locally inside the hook.
struct MentorState {
    std::vector<std::string> lines;
    std::size_t index{0};
    bool subtitles_only{false};
};

class MentorGuidanceDialogue final : public IDialogueHook {
public:
    void on_enter(World& world, std::uint32_t entity, const nlohmann::json& params) override {
        // Build a fresh state for this entity.
        MentorState st;

        const std::string context = params.value("context", std::string("scene_entry"));
        const std::string scene   = params.value("scene_id", std::string(""));
        const std::string reason  = params.value("reason", std::string(""));
        st.subtitles_only = params.value("mute_vo", false); // driven by accessibility settings via binding if desired

        st.lines = mentor_lines::select_block(context, scene, reason);
        if (st.lines.empty()) {
            // Fallback single line so the system always shows something graceful.
            st.lines.push_back("Stay present. Small choices shape the outcome.");
        }

        states_[entity] = st;

        // Light-touch hologram cue: tag the mentor NPC if present.
        auto mentor = world.find("mentor_npc");
        if (mentor != entt::null) {
            world.emplace_or_replace<CTag>(static_cast<std::uint32_t>(mentor), CTag{std::vector<std::string>{"mentor_dialogue_active"}});
        }

        // Also tag the host with a subtitle speaker tag for HUD overlays.
        world.emplace_or_replace<CTag>(entity, CTag{std::vector<std::string>{"subtitle_speaker:Mentor"}});
    }

    // on_line should output a single line per call. Return true if more remain, false when finished.
    bool on_line(World& world, std::uint32_t entity, std::string& out_speaker, std::string& out_text) override {
        auto it = states_.find(entity);
        if (it == states_.end()) {
            out_speaker.clear();
            out_text.clear();
            return false;
        }
        MentorState& st = it->second;
        if (st.index >= st.lines.size()) {
            out_speaker.clear();
            out_text.clear();
            return false;
        }

        out_speaker = "Mentor"; // for subtitle overlays
        out_text = st.lines[st.index++];

        // Surface the current subtitle to the world via tag for simple HUD test harnesses.
        // Test harness reads latest tag starting with "subtitle:" on this entity.
        world.emplace_or_replace<CTag>(entity, CTag{std::vector<std::string>{std::string("subtitle:") + out_text}});

        // If VO were integrated, we'd branch here. For now, st.subtitles_only gates nothing else.
        // TODO: Integrate VO playback service when available (respecting st.subtitles_only).

        return st.index < st.lines.size();
    }

    void on_exit(World& world, std::uint32_t entity) override {
        // Clear dialogue-active hint on mentor, if any.
        auto mentor = world.find("mentor_npc");
        if (mentor != entt::null) {
            // Remove only our marker; leave other tags intact by overwriting with an empty set if needed.
            world.emplace_or_replace<CTag>(static_cast<std::uint32_t>(mentor), CTag{std::vector<std::string>{}});
        }
        // Clean up local state.
        states_.erase(entity);
    }

    std::string id() const override { return "generated.mentor_guidance_dialogue"; }

private:
    std::unordered_map<std::uint32_t, MentorState> states_;
};

} // namespace ptv
